package com.securebiz.notification.repository;import com.securebiz.notification.api.NotificationDtos.NotificationResponse;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;import java.sql.*;import java.util.*;
@Repository public class NotificationRepository{private final JdbcClient jdbc;public NotificationRepository(JdbcClient jdbc){this.jdbc=jdbc;}public List<NotificationResponse>list(UUID user){return jdbc.sql("SELECT * FROM notifications WHERE user_id=:user ORDER BY created_at DESC LIMIT 100").param("user",user).query(this::map).list();}public int read(UUID id,UUID user){return jdbc.sql("UPDATE notifications SET read_at=COALESCE(read_at,now()) WHERE id=:id AND user_id=:user").param("id",id).param("user",user).update();}public void create(UUID user,String type,String title,String message,String resourceType,UUID resourceId){jdbc.sql("INSERT INTO notifications(id,user_id,type,title,message,resource_type,resource_id) VALUES(:id,:user,:type,:title,:message,:resourceType,:resourceId)").param("id",UUID.randomUUID()).param("user",user).param("type",type).param("title",title).param("message",message).param("resourceType",resourceType).param("resourceId",resourceId).update();}public void createForPermission(String permission,String type,String title,String message,String resourceType,UUID resourceId,UUID exclude){jdbc.sql("""
 INSERT INTO notifications(id,user_id,type,title,message,resource_type,resource_id)
 SELECT gen_random_uuid(),u.id,:type,:title,:message,:resourceType,:resourceId FROM users u
 WHERE u.status='ACTIVE' AND u.id<>:exclude AND EXISTS(SELECT 1 FROM user_roles ur JOIN role_permissions rp ON rp.role_id=ur.role_id JOIN permissions p ON p.id=rp.permission_id WHERE ur.user_id=u.id AND p.code=:permission)
 """).param("type",type).param("title",title).param("message",message).param("resourceType",resourceType).param("resourceId",resourceId).param("exclude",exclude).param("permission",permission).update();}private NotificationResponse map(ResultSet r,int n)throws SQLException{return new NotificationResponse(r.getObject("id",UUID.class),r.getString("type"),r.getString("title"),r.getString("message"),r.getString("resource_type"),r.getObject("resource_id",UUID.class),r.getTimestamp("read_at")==null?null:r.getTimestamp("read_at").toInstant(),r.getTimestamp("created_at").toInstant());}}
